BEGIN;

-- Provider discovery (src/discovery/, docs/PLATFORM_CONTRACT.md section 8.4). Candidates found
-- on the internet wait here for the operator. Nothing in this table is ever served on its own:
-- an operator approves a candidate, one live streamed tool call verifies it, and the operator
-- promotes it into gateway_provider_models (candidate_id), which the gateway reads only with
-- CATALOG_DB_MODELS=true.
--
-- Status: new (queued for review), approved (operator said yes; verification pending or
-- failed), verified (the live tool call passed: proposed for the catalog), rejected (operator
-- said no, or, with reviewed_at NULL, filtered out by the candidate policy), excluded (access
-- needs CAPTCHA solving, consumer chat scraping, client spoofing or another product's login;
-- never offered). model_id '' is the provider's own record.

CREATE TABLE public.zerox_provider_candidates (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  source text NOT NULL CHECK (source ~ '^[a-z0-9][a-z0-9:._-]{0,63}$'),
  provider text NOT NULL CHECK (provider ~ '^[a-z0-9][a-z0-9._-]{0,63}$'),
  model_id text NOT NULL DEFAULT '' CHECK (model_id = '' OR (model_id ~ '^[!-~]+$' AND char_length(model_id) <= 256)),
  display_name text CHECK (char_length(display_name) <= 200),
  context_window integer CHECK (context_window > 0),
  max_output_tokens integer CHECK (max_output_tokens > 0),
  supports_tools boolean,
  supports_vision boolean,
  evidence_url text CHECK (evidence_url ~ '^https://' AND char_length(evidence_url) <= 2048),
  status text NOT NULL DEFAULT 'new' CHECK (status IN ('new', 'approved', 'rejected', 'verified', 'excluded')),
  excluded_reason text CHECK (char_length(excluded_reason) <= 500),
  notes text CHECK (char_length(notes) <= 4000),
  review_notes text CHECK (char_length(review_notes) <= 2000),
  record jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(record) = 'object' AND octet_length(record::text) <= 32768),
  verification jsonb CHECK (verification IS NULL OR octet_length(verification::text) <= 8192),
  first_seen timestamptz NOT NULL DEFAULT now(),
  last_seen timestamptz NOT NULL DEFAULT now(),
  gone_at timestamptz,
  reviewed_at timestamptz,
  verified_at timestamptz,
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT zerox_provider_candidates_key UNIQUE (provider, model_id),
  CONSTRAINT zerox_provider_candidates_excluded_reason CHECK (status <> 'excluded' OR excluded_reason IS NOT NULL)
);

CREATE INDEX zerox_provider_candidates_status_idx ON public.zerox_provider_candidates (status, last_seen DESC);

ALTER TABLE public.zerox_provider_candidates ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.zerox_provider_candidates FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.zerox_provider_candidates TO service_role;

-- One row per discovery job (list:<source>, omniroute, research): when it may run next, what it
-- saw last time (snapshot, for the diff) and what it found.
CREATE TABLE public.zerox_discovery_state (
  job text PRIMARY KEY CHECK (job ~ '^[a-z0-9][a-z0-9:._-]{0,63}$'),
  next_run_at timestamptz,
  last_started_at timestamptz,
  last_finished_at timestamptz,
  last_ok_at timestamptz,
  last_error text CHECK (char_length(last_error) <= 1000),
  last_summary jsonb CHECK (last_summary IS NULL OR octet_length(last_summary::text) <= 16384),
  snapshot jsonb CHECK (snapshot IS NULL OR octet_length(snapshot::text) <= 262144),
  runs integer NOT NULL DEFAULT 0,
  spent_microusd bigint NOT NULL DEFAULT 0 CHECK (spent_microusd >= 0)
);

ALTER TABLE public.zerox_discovery_state ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.zerox_discovery_state FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.zerox_discovery_state TO service_role;

-- gateway_provider_models (20261006060000) was never read by the gateway. Rows promoted from a
-- verified candidate carry candidate_id; zerox_catalog_db_models() returns only those, so the
-- original seed rows stay inert.
ALTER TABLE public.gateway_provider_models
  ADD COLUMN IF NOT EXISTS candidate_id bigint UNIQUE REFERENCES public.zerox_provider_candidates (id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS display_name text CHECK (char_length(display_name) <= 200),
  ADD COLUMN IF NOT EXISTS promoted_at timestamptz;

-- ── Discovery writes ──

-- Upserts candidates found by a job. p_rows: [{source, provider, model_id, display_name,
-- context_window, max_output_tokens, supports_tools, supports_vision, evidence_url, status,
-- excluded_reason, notes, record}], status one of new / rejected (policy filter) / excluded.
-- Existing rows keep their source and every operator decision; newer evidence refreshes the
-- facts, an exclusion always wins, and a model row the policy filtered (rejected, no reviewer)
-- is queued again when new evidence passes the policy. A provider excluded at provider level
-- (model_id '') excludes all of its models.
CREATE FUNCTION public.zerox_candidates_upsert(p_rows jsonb)
RETURNS TABLE (id bigint, provider text, model_id text, status text, inserted boolean)
LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $$
#variable_conflict use_column
BEGIN
  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'invalid_candidates: p_rows must be a JSON array';
  END IF;
  IF jsonb_array_length(p_rows) > 500 THEN RAISE EXCEPTION 'invalid_candidates: at most 500 rows per call'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_to_recordset(p_rows) AS r(status text, excluded_reason text)
      WHERE r.status IS NULL OR r.status NOT IN ('new', 'rejected', 'excluded')
        OR (r.status = 'excluded' AND coalesce(r.excluded_reason, '') = '')) THEN
    RAISE EXCEPTION 'invalid_candidates: status must be new, rejected or excluded (with excluded_reason)';
  END IF;

  RETURN QUERY
  WITH input AS (
    SELECT DISTINCT ON (r.provider, coalesce(r.model_id, ''))
      r.source, r.provider, coalesce(r.model_id, '') AS model_id, r.display_name, r.context_window,
      r.max_output_tokens, r.supports_tools, r.supports_vision, r.evidence_url, r.status AS wanted,
      r.excluded_reason, r.notes, coalesce(r.record, '{}'::jsonb) AS record
    FROM jsonb_to_recordset(p_rows) AS r(source text, provider text, model_id text, display_name text,
      context_window integer, max_output_tokens integer, supports_tools boolean, supports_vision boolean,
      evidence_url text, status text, excluded_reason text, notes text, record jsonb)
    ORDER BY r.provider, coalesce(r.model_id, '')
  ), resolved AS (
    SELECT i.*, pe.excluded_reason AS provider_excluded
    FROM input AS i
    LEFT JOIN public.zerox_provider_candidates AS pe
      ON pe.provider = i.provider AND pe.model_id = '' AND pe.status = 'excluded' AND i.model_id <> ''
  )
  INSERT INTO public.zerox_provider_candidates AS c (source, provider, model_id, display_name, context_window,
    max_output_tokens, supports_tools, supports_vision, evidence_url, status, excluded_reason, notes, record)
  SELECT r.source, r.provider, r.model_id, r.display_name, r.context_window, r.max_output_tokens,
    r.supports_tools, r.supports_vision, r.evidence_url,
    CASE WHEN r.provider_excluded IS NOT NULL THEN 'excluded' ELSE r.wanted END,
    CASE WHEN r.provider_excluded IS NOT NULL THEN left('Provider excluded: ' || r.provider_excluded, 500)
      ELSE r.excluded_reason END,
    r.notes, r.record
  FROM resolved AS r
  ON CONFLICT ON CONSTRAINT zerox_provider_candidates_key DO UPDATE SET
    display_name = coalesce(EXCLUDED.display_name, c.display_name),
    context_window = coalesce(EXCLUDED.context_window, c.context_window),
    max_output_tokens = coalesce(EXCLUDED.max_output_tokens, c.max_output_tokens),
    supports_tools = coalesce(EXCLUDED.supports_tools, c.supports_tools),
    supports_vision = coalesce(EXCLUDED.supports_vision, c.supports_vision),
    evidence_url = coalesce(EXCLUDED.evidence_url, c.evidence_url),
    notes = coalesce(EXCLUDED.notes, c.notes),
    record = CASE WHEN EXCLUDED.record = '{}'::jsonb THEN c.record ELSE EXCLUDED.record END,
    status = CASE
      WHEN c.status = 'excluded' OR EXCLUDED.status = 'excluded' THEN 'excluded'
      WHEN c.model_id <> '' AND c.reviewed_at IS NULL AND c.status = 'rejected' AND EXCLUDED.status = 'new' THEN 'new'
      ELSE c.status END,
    excluded_reason = CASE WHEN c.status <> 'excluded' AND EXCLUDED.status = 'excluded'
      THEN EXCLUDED.excluded_reason ELSE c.excluded_reason END,
    last_seen = now(), gone_at = NULL, updated_at = now()
  RETURNING c.id, c.provider, c.model_id, c.status, (c.xmax::text = '0');

  -- An excluded provider takes its models with it; nothing that is not verified stays promoted.
  UPDATE public.zerox_provider_candidates AS m
    SET status = 'excluded', excluded_reason = left('Provider excluded: ' || p.excluded_reason, 500), updated_at = now()
  FROM public.zerox_provider_candidates AS p
  WHERE p.model_id = '' AND p.status = 'excluded' AND m.provider = p.provider AND m.model_id <> ''
    AND m.status <> 'excluded';
  UPDATE public.gateway_provider_models AS g SET enabled = false, updated_at = now()
  FROM public.zerox_provider_candidates AS c
  WHERE g.candidate_id = c.id AND g.enabled AND c.status <> 'verified';
END;
$$;

-- A provider's public list was read: listed ids are seen now, the provider's other candidates
-- are marked gone (gone_at). An empty list is refused so a broken upstream never empties it.
CREATE FUNCTION public.zerox_candidates_sync_listed(p_provider text, p_model_ids text[])
RETURNS TABLE (seen integer, gone integer)
LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $$
#variable_conflict use_column
DECLARE
  v_seen integer;
  v_gone integer;
BEGIN
  IF p_provider IS NULL OR p_provider !~ '^[a-z0-9][a-z0-9._-]{0,63}$' THEN
    RAISE EXCEPTION 'invalid_listing: p_provider is not a provider id';
  END IF;
  IF p_model_ids IS NULL OR cardinality(p_model_ids) = 0 THEN
    RAISE EXCEPTION 'invalid_listing: an empty list never marks candidates gone';
  END IF;
  IF cardinality(p_model_ids) > 20000 THEN RAISE EXCEPTION 'invalid_listing: at most 20000 ids'; END IF;
  UPDATE public.zerox_provider_candidates AS c SET last_seen = now(), gone_at = NULL
  WHERE c.provider = p_provider AND (c.model_id = '' OR c.model_id = ANY (p_model_ids));
  GET DIAGNOSTICS v_seen = ROW_COUNT;
  UPDATE public.zerox_provider_candidates AS c SET gone_at = now()
  WHERE c.provider = p_provider AND c.model_id <> '' AND c.gone_at IS NULL AND NOT (c.model_id = ANY (p_model_ids));
  GET DIAGNOSTICS v_gone = ROW_COUNT;
  RETURN QUERY SELECT v_seen, v_gone;
END;
$$;

-- ── Review ──

-- Candidates for the review page. p_status also takes 'filtered' (rejected by the policy, no
-- reviewer); 'rejected' then means rejected by the operator. The full record only comes with p_id.
CREATE FUNCTION public.zerox_candidates_list(p_id bigint DEFAULT NULL, p_status text DEFAULT NULL,
  p_provider text DEFAULT NULL, p_search text DEFAULT NULL, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
RETURNS TABLE (id bigint, source text, provider text, model_id text, display_name text, context_window integer,
  max_output_tokens integer, supports_tools boolean, supports_vision boolean, evidence_url text, status text,
  excluded_reason text, notes text, review_notes text, record jsonb, verification jsonb, first_seen timestamptz,
  last_seen timestamptz, gone_at timestamptz, reviewed_at timestamptz, verified_at timestamptz,
  promoted_model_id text, promoted boolean, total_count bigint)
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = '' AS $$
  SELECT c.id, c.source, c.provider, c.model_id, c.display_name, c.context_window, c.max_output_tokens,
    c.supports_tools, c.supports_vision, c.evidence_url, c.status, c.excluded_reason, c.notes, c.review_notes,
    CASE WHEN p_id IS NULL THEN NULL ELSE c.record END, c.verification, c.first_seen, c.last_seen, c.gone_at,
    c.reviewed_at, c.verified_at, g.public_model_id, coalesce(g.enabled, false), count(*) OVER ()
  FROM public.zerox_provider_candidates AS c
  LEFT JOIN public.gateway_provider_models AS g ON g.candidate_id = c.id
  WHERE (p_id IS NULL OR c.id = p_id)
    AND (p_status IS NULL
      OR (p_status = 'filtered' AND c.status = 'rejected' AND c.reviewed_at IS NULL)
      OR (p_status = 'rejected' AND c.status = 'rejected' AND c.reviewed_at IS NOT NULL)
      OR (p_status NOT IN ('filtered', 'rejected') AND c.status = p_status))
    AND (p_provider IS NULL OR c.provider = p_provider)
    AND (p_search IS NULL OR strpos(lower(c.provider || ' ' || c.model_id || ' ' || coalesce(c.display_name, '')),
      lower(left(p_search, 100))) > 0)
  ORDER BY (c.status = 'new') DESC, c.last_seen DESC, c.id DESC
  LIMIT least(greatest(coalesce(p_limit, 100), 1), 500) OFFSET greatest(coalesce(p_offset, 0), 0);
$$;

-- Operator decision on one or more candidates. approve: new or rejected (or approved again, to
-- re-run verification) becomes approved; reject: anything not excluded becomes rejected and its
-- catalog row, if any, is disabled. Excluded candidates can never be approved.
CREATE FUNCTION public.zerox_candidates_review(p_ids bigint[], p_action text, p_note text DEFAULT NULL)
RETURNS TABLE (id bigint, status text)
LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $$
#variable_conflict use_column
BEGIN
  IF p_action IS NULL OR p_action NOT IN ('approve', 'reject') THEN
    RAISE EXCEPTION 'invalid_review: p_action must be approve or reject';
  END IF;
  IF p_ids IS NULL OR cardinality(p_ids) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'invalid_review: p_ids must hold 1 to 200 ids';
  END IF;
  IF char_length(p_note) > 2000 THEN RAISE EXCEPTION 'invalid_review: p_note is longer than 2000 characters'; END IF;
  IF p_action = 'approve' AND EXISTS (SELECT 1 FROM public.zerox_provider_candidates AS c
      WHERE c.id = ANY (p_ids) AND c.status = 'excluded') THEN
    RAISE EXCEPTION 'candidate_excluded: excluded candidates are never offered';
  END IF;
  RETURN QUERY UPDATE public.zerox_provider_candidates AS c
    SET status = CASE p_action WHEN 'approve' THEN 'approved' ELSE 'rejected' END,
      reviewed_at = now(), review_notes = coalesce(nullif(p_note, ''), c.review_notes), updated_at = now()
    WHERE c.id = ANY (p_ids) AND c.status <> 'excluded'
      AND (p_action = 'reject' OR c.status IN ('new', 'rejected', 'approved'))
    RETURNING c.id, c.status;
  IF p_action = 'reject' THEN
    UPDATE public.gateway_provider_models AS g SET enabled = false, updated_at = now()
    WHERE g.candidate_id = ANY (p_ids) AND g.enabled;
  END IF;
END;
$$;

-- Result of the live streamed tool call for an approved (or verified) candidate. Passing makes
-- it verified (proposed for the catalog); failing leaves it approved and disables any catalog row.
CREATE FUNCTION public.zerox_candidate_record_verification(p_id bigint, p_passed boolean, p_result jsonb)
RETURNS TABLE (id bigint, status text)
LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $$
#variable_conflict use_column
BEGIN
  IF p_passed IS NULL OR p_result IS NULL OR jsonb_typeof(p_result) <> 'object' THEN
    RAISE EXCEPTION 'invalid_verification: p_passed and an object p_result are required';
  END IF;
  RETURN QUERY UPDATE public.zerox_provider_candidates AS c
    SET status = CASE WHEN p_passed THEN 'verified' ELSE 'approved' END,
      verified_at = CASE WHEN p_passed THEN now() ELSE c.verified_at END,
      verification = p_result, updated_at = now()
    WHERE c.id = p_id AND c.model_id <> '' AND c.status IN ('approved', 'verified')
    RETURNING c.id, c.status;
  IF NOT FOUND THEN RAISE EXCEPTION 'candidate_not_approved: only approved models can be verified'; END IF;
  IF NOT p_passed THEN
    UPDATE public.gateway_provider_models AS g SET enabled = false, updated_at = now()
    WHERE g.candidate_id = p_id AND g.enabled;
  END IF;
END;
$$;

-- Operator promotion of a verified candidate into gateway_provider_models. The gateway computes
-- the public id and the provider from its code-defined templates (src/catalog.js) and passes them.
CREATE FUNCTION public.zerox_candidate_promote(p_id bigint, p_public_model_id text, p_provider_id text,
  p_provider_model_id text, p_display_name text, p_context_window integer, p_max_output_tokens integer,
  p_supports_vision boolean DEFAULT false)
RETURNS TABLE (public_model_id text, enabled boolean)
LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $$
#variable_conflict use_column
DECLARE
  v_status text;
BEGIN
  SELECT c.status INTO v_status FROM public.zerox_provider_candidates AS c WHERE c.id = p_id FOR UPDATE;
  IF v_status IS DISTINCT FROM 'verified' THEN
    RAISE EXCEPTION 'candidate_not_verified: only verified candidates can join the catalog';
  END IF;
  IF p_public_model_id IS NULL OR p_public_model_id !~ '^[!-~]+$' OR char_length(p_public_model_id) > 256
      OR p_provider_model_id IS NULL OR p_provider_model_id !~ '^[!-~]+$' OR char_length(p_provider_model_id) > 256 THEN
    RAISE EXCEPTION 'invalid_promotion: model ids are required';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.gateway_providers AS p WHERE p.id = p_provider_id AND p.enabled) THEN
    RAISE EXCEPTION 'invalid_promotion: provider % is not an enabled gateway provider', p_provider_id;
  END IF;
  IF EXISTS (SELECT 1 FROM public.gateway_provider_models AS g
      WHERE g.public_model_id = p_public_model_id AND g.candidate_id IS DISTINCT FROM p_id) THEN
    RAISE EXCEPTION 'public_model_id_taken: % is already in gateway_provider_models', p_public_model_id;
  END IF;
  DELETE FROM public.gateway_provider_models AS g WHERE g.candidate_id = p_id AND g.public_model_id <> p_public_model_id;
  RETURN QUERY INSERT INTO public.gateway_provider_models AS g (public_model_id, provider_id, provider_model_id,
    enabled, supports_streaming, supports_tools, supports_parallel_tools, supports_vision, supports_reasoning,
    context_window, max_output_tokens, input_cost_per_million, output_cost_per_million, tier, routing_priority,
    candidate_id, display_name, promoted_at, updated_at)
  VALUES (p_public_model_id, p_provider_id, p_provider_model_id, true, true, true, true, coalesce(p_supports_vision, false),
    false, p_context_window, p_max_output_tokens, 0, 0, 'free', 100, p_id, left(p_display_name, 200), now(), now())
  ON CONFLICT (public_model_id) DO UPDATE SET provider_id = EXCLUDED.provider_id,
    provider_model_id = EXCLUDED.provider_model_id, enabled = true, supports_vision = EXCLUDED.supports_vision,
    context_window = EXCLUDED.context_window, max_output_tokens = EXCLUDED.max_output_tokens,
    display_name = EXCLUDED.display_name, promoted_at = now(), updated_at = now()
  RETURNING g.public_model_id, g.enabled;
END;
$$;

CREATE FUNCTION public.zerox_candidate_demote(p_id bigint)
RETURNS TABLE (public_model_id text, enabled boolean)
LANGUAGE sql SECURITY INVOKER SET search_path = '' AS $$
  UPDATE public.gateway_provider_models AS g SET enabled = false, updated_at = now()
  WHERE g.candidate_id = p_id RETURNING g.public_model_id, g.enabled;
$$;

-- What the gateway may add to its code-defined catalog: promoted rows of candidates that are
-- still verified, on enabled providers, free tier only.
CREATE FUNCTION public.zerox_catalog_db_models()
RETURNS TABLE (public_model_id text, provider_id text, provider_model_id text, display_name text,
  context_window integer, max_output_tokens integer, supports_vision boolean, candidate_id bigint)
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = '' AS $$
  SELECT g.public_model_id, g.provider_id, g.provider_model_id, g.display_name, g.context_window,
    g.max_output_tokens, g.supports_vision, g.candidate_id
  FROM public.gateway_provider_models AS g
  JOIN public.zerox_provider_candidates AS c ON c.id = g.candidate_id
  JOIN public.gateway_providers AS p ON p.id = g.provider_id
  WHERE g.enabled AND p.enabled AND c.status = 'verified' AND g.tier = 'free'
  ORDER BY g.public_model_id
  LIMIT 200;
$$;

-- ── Jobs ──

-- Claims the due jobs (with p_force, also jobs that are not due yet) for one run. A claimed job
-- is leased for p_lease_seconds: until it finishes or the lease ends, nothing claims it again.
CREATE FUNCTION public.zerox_discovery_claim(p_jobs text[], p_force boolean DEFAULT false, p_lease_seconds integer DEFAULT 1200)
RETURNS TABLE (job text, snapshot jsonb, last_ok_at timestamptz, runs integer)
LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $$
#variable_conflict use_column
BEGIN
  IF p_jobs IS NULL OR cardinality(p_jobs) NOT BETWEEN 1 AND 20
      OR EXISTS (SELECT 1 FROM unnest(p_jobs) AS j(name) WHERE j.name IS NULL OR j.name !~ '^[a-z0-9][a-z0-9:._-]{0,63}$') THEN
    RAISE EXCEPTION 'invalid_jobs: p_jobs must hold 1 to 20 job ids';
  END IF;
  INSERT INTO public.zerox_discovery_state AS s (job) SELECT DISTINCT j.name FROM unnest(p_jobs) AS j(name)
  ON CONFLICT (job) DO NOTHING;
  RETURN QUERY UPDATE public.zerox_discovery_state AS s
    SET next_run_at = now() + make_interval(secs => least(greatest(coalesce(p_lease_seconds, 1200), 60), 3600)),
      last_started_at = now(), runs = s.runs + 1
    WHERE s.job = ANY (p_jobs) AND (s.next_run_at IS NULL OR s.next_run_at <= now()
      OR (coalesce(p_force, false) AND s.last_finished_at IS NOT NULL AND s.last_finished_at >= s.last_started_at))
    RETURNING s.job, s.snapshot, s.last_ok_at, s.runs;
END;
$$;

CREATE FUNCTION public.zerox_discovery_finish(p_job text, p_ok boolean, p_next_run_seconds integer,
  p_snapshot jsonb DEFAULT NULL, p_summary jsonb DEFAULT NULL, p_error text DEFAULT NULL, p_spent_microusd bigint DEFAULT 0)
RETURNS void
LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $$
BEGIN
  UPDATE public.zerox_discovery_state AS s SET
    next_run_at = now() + make_interval(secs => least(greatest(coalesce(p_next_run_seconds, 86400), 60), 2592000)),
    last_finished_at = now(),
    last_ok_at = CASE WHEN p_ok THEN now() ELSE s.last_ok_at END,
    last_error = CASE WHEN p_ok THEN NULL ELSE left(coalesce(p_error, 'failed'), 1000) END,
    last_summary = coalesce(p_summary, s.last_summary),
    -- A failed paid run still records its next budget (research halves its searches).
    snapshot = coalesce(p_snapshot, s.snapshot),
    spent_microusd = s.spent_microusd + greatest(coalesce(p_spent_microusd, 0), 0)
  WHERE s.job = p_job;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown_job: %', left(p_job, 64); END IF;
END;
$$;

-- Review page header: candidate counts (rejected rows without a reviewer count as 'filtered')
-- and the state of every job.
CREATE FUNCTION public.zerox_discovery_overview()
RETURNS TABLE (overview jsonb)
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = '' AS $$
  SELECT jsonb_build_object(
    'counts', coalesce((SELECT jsonb_object_agg(t.k, t.n) FROM (
      SELECT CASE WHEN c.status = 'rejected' AND c.reviewed_at IS NULL THEN 'filtered' ELSE c.status END AS k,
        count(*) AS n
      FROM public.zerox_provider_candidates AS c GROUP BY 1) AS t), '{}'::jsonb),
    'jobs', coalesce((SELECT jsonb_agg(jsonb_build_object('job', s.job, 'next_run_at', s.next_run_at,
      'last_started_at', s.last_started_at, 'last_finished_at', s.last_finished_at, 'last_ok_at', s.last_ok_at,
      'last_error', s.last_error, 'last_summary', s.last_summary, 'runs', s.runs, 'spent_microusd', s.spent_microusd)
      ORDER BY s.job) FROM public.zerox_discovery_state AS s), '[]'::jsonb));
$$;

-- What the research agent is told is already known: every provider with its own status and up
-- to 12 of its live candidate model ids.
CREATE FUNCTION public.zerox_candidates_research_context()
RETURNS TABLE (provider text, status text, models text[])
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = '' AS $$
  SELECT c.provider,
    max(CASE WHEN c.model_id = '' THEN c.status END),
    coalesce((array_agg(c.model_id ORDER BY c.last_seen DESC, c.model_id)
      FILTER (WHERE c.model_id <> '' AND c.status IN ('new', 'approved', 'verified') AND c.gone_at IS NULL))[1:12], '{}')
  FROM public.zerox_provider_candidates AS c
  GROUP BY c.provider
  ORDER BY c.provider
  LIMIT 500;
$$;

