signup":{"card_required":false,"kyc":"none mentioned in docs","india_available":true,"region_notes":"Login is through a Gitee account. From an Indian IP, gitee.com/signup offers Google, GitHub or email sign-up. No real-name step appears in MoArk docs. The free token itself hasn't been tested from India."},"limits":{"rpd":100,"scope":"account","other":"100 free calls per day per account, shared across all models (trial token). Async tasks: at most 5 at once per user. The Serverless API has no separate concurrency cap (shared public pool)."},"reset":{"when":"daily","timezone":"Asia/Shanghai"},"terms":"Trial token is for experience only ('仅供体验'); paid resource packs are non-refundable.","data_training_free_tier":"not stated in docs","health_probe":{"request":"GET https://api.moark.com/v1/models (public, no key, 208 IDs)","auth_required":false},"sources":["https://moark.com/docs/FAQ","https://moark.com/docs/getting-started","https://moark.com/docs/products/apis","https://moark.com/docs/integrations/Development-Tools/open_code","https://moark.com/serverless-api","https://api.moark.com/v1/models"],"verified_date":"2026-10-19","layers":["web-2026-10-19"],"notes":"100 calls/day is small but includes frontier coding models if the trial token covers them. Treat it as a low-priority fallback pool."}},{"provider":"moark-gitee-ai","model_id":"DeepSeek-V4.1-Flash-1017","context_window":1048576,"status":"rejected","notes":"tool calling not published","record":{"notes":"Plaza card badges show '1M' and '384K' (probably context and max output; not labelled). List price ¥2/¥8 per M. Trial-token coverage assumed from the 'all featured models' wording."}},{"provider":"moark-gitee-ai","model_id":"GLM-5.3-Flash","context_window":1048576,"status":"rejected","notes":"tool calling not published","record":{"notes":"Card shows 128K and 1M (read as 1M context, 128K output). List price ¥0.8/¥2.8. Card badges show '128K' and '1M' (not labelled; 1M is probably context)."}},{"provider":"moark-gitee-ai","model_id":"Qwen3.8-Flash","context_window":1048576,"supports_tools":true,"status":"new","record":{"notes":"Function Calling badge."}},{"provider":"moark-gitee-ai","model_id":"DeepSeek-V4-Pro","supports_tools":true,"status":"rejected","notes":"context window not published","record":{"notes":"Plus DeepSeek-V4-Pro-0813 (1M, Function Calling) and DeepSeek-V4-Flash-0731 (1M)."}},{"provider":"moark-gitee-ai","model_id":"Kimi-K2.7-Code","context_window":262144,"status":"rejected","notes":"tool calling not published","record":{"notes":"Coding agent model."}},{"provider":"moark-gitee-ai","model_id":"GLM-5.2","context_window":1048576,"status":"rejected","notes":"tool calling not published","record":{"notes":"Card badges show '128K' and '1M' (not labelled; 1M is probably context)."}},{"provider":"moark-gitee-ai","model_id":"MiniMax-M3","context_window":1048576,"supports_tools":true,"status":"new"},{"provider":"moark-gitee-ai","model_id":"Qwen3-Coder-Flash","status":"rejected","notes":"tool calling not published","record":{"notes":"Coding model."}},{"provider":"modal","display_name":"Modal","status":"rejected","notes":"Reference record from the 19 Oct research (free_status=trial_only).","record":{"id":"modal","name":"Modal","kind":"trial_credit","free_status":"trial_only","base_url":"https://api.modal.ai/v1","api_shape":"openai","auth":"api_key","limits":{"other":"$30/month free credits for new accounts (freeNote)"},"health_probe":{"request":"https://api.modal.ai/v1/models"},"sources":[],"layers":["omniroute-catalog"],"notes":"Serves user-deployed OpenAI-compatible apps (https://<workspace>--<app>.modal.run/v1); not a hosted model catalog. Registry base https://api.modal.ai/v1 is a placeholder."}},{"provider":"modal","model_id":"google/gemini-2.0-flash","status":"rejected","notes":"tool calling not published; trial credit only","record":{"notes":"Gemini 2.0 Flash; registry seed list (OmniRoute does not mark per-model free status)"}},{"provider":"modelscope-cn","display_name":"ModelScope API-Inference (modelscope.cn, mainland site)","status":"rejected","notes":"Reference record from the 19 Oct research (free_status=active).","evidence_url":"https://www.modelscope.cn/docs/model-service/API-Inference/intro","record":{"id":"modelscope-cn","name":"ModelScope API-Inference (modelscope.cn, mainland site)","kind":"official_free_tier","free_status":"active","free_status_note":"API-Inference is still free, but calls now spend free 'Magicubes': about 0.5 per call for lightweight models, 1 for standard and 2 for flagship. Each day brings 200 short-term Magicubes for signing in plus 50 for having a linked Alibaba Cloud account, both expiring after 24 h. That is about 125 flagship or 250 standard calls a day. This replaced the older flat 2000 calls/day (500 per model) scheme","base_url":"https://api-inference.modelscope.cn/v1","api_shape":["openai","anthropic"],"auth":"Authorization: Bearer <ModelScope access token> (modelscope.cn/my/myaccesstoken)","signup":{"card_required":false,"kyc":"ModelScope account must be linked to an Alibaba Cloud account that has passed real-name verification. On aliyun.com that means Alipay or face verification.","india_available":false,"region_notes":"A mainland Alibaba Cloud real-name check isn't realistic for an Indian user. Use modelscope-intl, which still needs an Alibaba Cloud account with real-name verification. Magicubes also need a verified email on the profile."},"limits":{"concurrency":1,"scope":"account","other":"Budget is Magicubes, not calls: 200/day (login) + 50/day (Alibaba Cloud linked), expiring after 24 h, plus one-time 90-day bonuses (email 50, bio 50, profile 50). Cost about 0.5/1/2 per call. Concurrency is dynamically limited by load, with 'normal single-concurrency' guaranteed."},"reset":{"when":"daily; short-term Magicubes expire 24 h after issuance","timezone":"Asia/Shanghai"},"terms":"Non-commercial, non-profit trial service; docs say not for high-concurrency/SLA production use.","data_traini